        leaves = scoretools.make_leaves([0], [power_of_two_division])
        tuplet = scoretools.Tuplet(tuplet_multiplier, leaves)
        return tuplet

    def _make_music(self, duration_pairs, seeds):
        result = []
        for duration_pair in duration_pairs:
